using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Runtime.Serialization.Json;using Lumina;
public static class PersistenceTests {
    static void Check(bool value,string label){if(!value)throw new Exception(label);}
    static byte[] Json<T>(T value){using(var stream=new MemoryStream()){new DataContractJsonSerializer(typeof(T)).WriteObject(stream,value);return stream.ToArray();}}
    static void Write(string path,byte[] bytes){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllBytes(path,bytes);}
    static void Clean(){if(Directory.Exists(Store.Folder))Directory.Delete(Store.Folder,true);Directory.CreateDirectory(Store.Folder);}
    public static int Main(){try{
        Clean();var app=new Entry{Name="旧版游戏",Path=@"C:\Games\A.lnk",LaunchTarget=@"C:\Launcher\start.exe",Group="游戏",ExtraGroups=new List<string>{"常用"}};
        var old=new Preferences{BoardIconSize=66};old.Dock.IconSize=58;old.Apps.Add(app);old.Removed.Add(app.Path);old.RemovedIdentities.Add(RemovalRules.Identity(app));Write(Store.FileName,Json(old));
        var p=Store.Load();Check(p.Apps.Count==1&&FeatureRules.InGroup(p.Apps[0],"游戏")&&FeatureRules.InGroup(p.Apps[0],"常用"),"old live entries and all memberships survive conflicting tombstones");Check(p.Dock.IconSize==58&&!p.BoardDismissOnDeactivate&&!RemovalRules.Blocked(p,p.Apps[0]),"old DIY preserved, stale tombstones reconciled");Check(Directory.GetFiles(Path.Combine(Store.Folder,"snapshots"),"upgrade-*.json").Length==1,"raw upgrade layout preserved");p.BoardDismissOnDeactivate=true;Store.Save(p);p=Store.Load();Check(p.BoardDismissOnDeactivate&&p.FormatVersion==2&&p.Apps.Count==1,"schema upgrade roundtrip");
        EntryRules.Remove(p,new[]{app.Path},"全部");Store.Save(p);File.WriteAllText(Store.FileName,"{truncated");p=Store.Load();Check(p.Apps.Count==0&&Store.RecoveryMessage!=null,"latest durable mirror survives primary corruption");
        File.Delete(Store.FileName);p=Store.Load();Check(p.Apps.Count==0&&Store.RecoveryMessage!=null,"missing primary recovers instead of resetting");
        File.WriteAllText(Store.FileName+".last-good","broken");p=Store.Load();Check(p.Apps.Count==0,"prior snapshot plus journal does not resurrect deleted app");
        var recovered=Store.HistoricalEntries();Check(recovered.Any(x=>x.Path==app.Path&&FeatureRules.InGroup(x,"游戏")),"historical scan finds preupgrade missing app");Check(EntryRecoveryRules.Candidates(p,recovered).Count==1,"only missing entries/memberships offered");p.BoardMaterial.Tint="#123456";EntryRecoveryRules.Restore(p,recovered);Store.Save(p);Check(Store.Load().Apps.Count==1&&Store.Load().BoardMaterial.Tint=="#123456","selected restore persists and keeps current DIY");
        var stale=new RemovalJournal{Paths=new List<string>{app.Path},Identities=new List<string>{RemovalRules.Identity(app)}};Write(Path.Combine(Store.Folder,"removed.json"),Json(stale));Check(Store.Load().Apps.Count==1,"stale journal cannot erase a valid manually restored layout");
        var history=FeatureRules.Copy(app);history.ExtraGroups.Add("办公");p=Store.Load();EntryRecoveryRules.Restore(p,new[]{history});Check(p.Apps.Count==1&&FeatureRules.InGroup(p.Apps[0],"办公"),"restore missing membership without duplicate or current-group loss");
        for(int i=0;i<36;i++){p.Apps[0].Name="软件"+i;Store.Save(p);}Check(Directory.GetFiles(Path.Combine(Store.Folder,"snapshots"),"layout-*.json").Length<=30,"snapshot count bounded");
        byte[] committed=File.ReadAllBytes(Store.FileName);p=Store.Load();File.WriteAllText(Store.FileName+".last-good","broken");File.WriteAllText(Store.FileName,"broken");p=Store.Load();Store.Save(p);Check(Store.ReadLayout(File.ReadAllBytes(Store.FileName)).Apps.Count==1&&File.ReadAllBytes(Store.FileName+".previous").Length>10,"save after recovery does not rotate damaged primary over good previous");
        Clean();File.WriteAllText(Store.FileName,"broken");bool refused=false;try{Store.Load();}catch(InvalidDataException){refused=true;}Check(refused&&File.ReadAllText(Store.FileName)=="broken","all-invalid config refuses silent reset or overwrite");
        Clean();Write(Store.FileName+".before-widget-recovery-old",Json(old));p=Store.Load();Check(p.Apps.Count==1&&Store.HistoricalEntries().Any(a=>a.Path==app.Path),"older widget recovery copy remains usable when main layout is missing");Clean();p=Store.Load();p.Apps.Add(app);Store.Save(p);var saved=File.ReadAllBytes(Store.FileName);p.LearnedGroups["invalid"]="valid";string blocker=Store.FileName+".previous";Directory.CreateDirectory(blocker);bool failed=false;try{Store.Save(p);}catch(IOException){failed=true;}Check(failed&&File.ReadAllBytes(Store.FileName).SequenceEqual(saved),"forced replace failure preserves committed layout");
        Console.WriteLine("PASS: production Store durability, migration, exact live-entry precedence, corruption/missing-file recovery, deletion journal, explicit recovery/current DIY, 30 snapshots, all-invalid preservation and failed atomic replacement.");return 0;
    }finally{if(Directory.Exists(Store.Folder))Directory.Delete(Store.Folder,true);}}
}
